def process(values):
    """Task execution docstring."""
    if not values:
        return None
    if any(value is None for value in values):
        raise ValueError("Missing value")
    return [sum(values[i:i+3])/3 for i in range(len(values)-2)]
sample = [2.4, 3.1, 1.8, 4.0]
result = process(sample)
print(result)

