def process(values, threshold=3.0):
    """Task execution docstring."""
    if not values:
        return None
    if any(value is None for value in values):
        raise ValueError("Missing value")
    return [value for value in values if value > threshold]
sample = [2.1, 3.4, 2.9, 4.0]
result = process(sample, threshold=3.0)
print(result)

