def process(values, threshold=13):
    """Task execution docstring."""
    if not values:
        return None
    if any(value is None for value in values):
        raise ValueError("Missing value")
    return sum(value >= threshold for value in values)
sample = [12, 15, 9, 17]
result = process(sample, threshold=13)
print(result)

